/* config.h for the Android build.
 *
 * On the desktop this header is generated by configure (see configure.ac and
 * include/config.h). Android is built with CMake, so the equivalent defines
 * live here. Single-player only: multiplayer needs x87 floating point for
 * deterministic sync (-mfpmath=387), which ARM does not have.
 */

#define PACKAGE "7kaa"
#define PACKAGE_BUGREPORT "the3dfxdude@gmail.com"
#define PACKAGE_NAME "7kaa"
#define PACKAGE_STRING "7kaa 2.15.6"
#define PACKAGE_TARNAME "7kaa"
#define PACKAGE_URL "http://7kfans.com/"
#define PACKAGE_VERSION "2.15.6"
#define VERSION "2.15.6"

#define STDC_HEADERS 1
#define HAVE_CXX11 1
#define HAVE_INTTYPES_H 1
#define HAVE_STDINT_H 1
#define HAVE_STDIO_H 1
#define HAVE_STDLIB_H 1
#define HAVE_STRINGS_H 1
#define HAVE_STRING_H 1
#define HAVE_STRING_STRCASECMP 1
#define HAVE_SYS_STAT_H 1
#define HAVE_SYS_TYPES_H 1
#define HAVE_UNISTD_H 1
#define HAVE_SETENV 1

#define USE_SDL 1
#define USE_POSIX 1
#define USE_OPENAL 1
#define OPENAL_AL_H <AL/al.h>
#define OPENAL_ALC_H <AL/alc.h>

#define NO_MEM_CLASS 1

/* The 'register' keyword is not allowed in C++17 (configure.ac defines
 * REGISTER as empty for the same reason). */
#define REGISTER

/* Single-player build: no multiplayer menu, no enet, no x87 sync guarantee,
 * so HAVE_KNOWN_BUILD stays undefined. No gettext/NLS, no libcurl. */
#define DISABLE_MULTI_PLAYER 1
